package com.bicheon.advisor.dev356;
import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import android.view.*;import android.util.*;import java.nio.*;
public class AdvisorEngine{static final int C=7;Context c;MediaProjection p;WindowManager w;ImageReader ir;VirtualDisplay vd;HandlerThread ht;Handler h;Overlay o;int sw,sh,dpi;volatile boolean run;AdvisorEngine(Context x,MediaProjection y){c=x.getApplicationContext();p=y;}void start(){w=(WindowManager)c.getSystemService(Context.WINDOW_SERVICE);DisplayMetrics dm=new DisplayMetrics();w.getDefaultDisplay().getRealMetrics(dm);sw=dm.widthPixels;sh=dm.heightPixels;dpi=dm.densityDpi;o=new Overlay(c);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);w.addView(o,lp);ht=new HandlerThread("bicheon");ht.start();h=new Handler(ht.getLooper());ir=ImageReader.newInstance(sw,sh,PixelFormat.RGBA_8888,2);vd=p.createVirtualDisplay("bicheon",sw,sh,dpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,ir.getSurface(),null,h);run=true;ir.setOnImageAvailableListener(r->{Image im=null;try{im=r.acquireLatestImage();if(im==null)return;Image.Plane q=im.getPlanes()[0];ByteBuffer b=q.getBuffer();int rs=q.getRowStride(),ps=q.getPixelStride();G g=detect(b,rs,ps);if(g==null){o.clear();return;}int[][]bd=read(b,rs,ps,g);Solver.Move m=Solver.choose(bd,g.rows,C);if(m==null)o.clear();else o.set(g,m);}catch(Throwable t){o.clear();}finally{if(im!=null)try{im.close();}catch(Throwable t){}}},h);}G detect(ByteBuffer b,int rs,int ps){int cell=sw/8;for(int rows:new int[]{11,12}){int bh=rows*cell;if(bh>sh-200)continue;for(int y=Math.max(100,sh/5);y<sh-bh-80;y+=Math.max(12,cell/3)){int x=(sw-cell*C)/2;int good=0;for(int r=0;r<rows;r+=2)for(int k=0;k<C;k++)if(type(b,rs,ps,x+k*cell+cell/2,y+r*cell+cell/2)>=0)good++;if(good>=rows/2*C*2/3)return new G(x,y,cell,rows);}}return null;}int[][]read(ByteBuffer b,int rs,int ps,G g){int[][]z=new int[g.rows][C];for(int r=0;r<g.rows;r++)for(int k=0;k<C;k++)z[r][k]=type(b,rs,ps,g.x+k*g.cell+g.cell/2,g.y+r*g.cell+g.cell/2);return z;}int type(ByteBuffer b,int rs,int ps,int x,int y){if(x<0||y<0||x>=sw||y>=sh)return-1;int o=y*rs+x*ps;if(o+2>=b.limit())return-1;int r=b.get(o)&255,g=b.get(o+1)&255,bl=b.get(o+2)&255,m=Math.max(r,Math.max(g,bl)),n=Math.min(r,Math.min(g,bl));if(m<45)return-1;if(r>g+30&&r>bl+15)return 0;if(g>r+18&&g>bl-5)return 1;if(bl>r+25&&bl>g+10)return 2;if(r>g+12&&bl>g+12)return 3;if(n>130&&m-n<75)return 4;if(r>110&&g>80&&bl<130)return 5;return-1;}void stop(){run=false;try{if(vd!=null)vd.release();}catch(Throwable t){}try{if(ir!=null)ir.close();}catch(Throwable t){}try{if(ht!=null)ht.quitSafely();}catch(Throwable t){}try{if(o!=null&&w!=null)w.removeView(o);}catch(Throwable t){}}static class G{int x,y,cell,rows;G(int a,int b,int c,int d){x=a;y=b;cell=c;rows=d;}}static class Overlay extends View{Paint p=new Paint(1);volatile G g;volatile Solver.Move m;Overlay(Context c){super(c);p.setColor(Color.rgb(30,230,90));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(6);}void set(G a,Solver.Move b){g=a;m=b;postInvalidate();}void clear(){g=null;m=null;postInvalidate();}protected void onDraw(Canvas c){G a=g;Solver.Move b=m;if(a==null||b==null)return;float s=a.cell,x1=a.x+b.c1*s,y1=a.y+b.r1*s,x2=a.x+b.c2*s,y2=a.y+b.r2*s;c.drawRect(x1+3,y1+3,x1+s-3,y1+s-3,p);c.drawRect(x2+3,y2+3,x2+s-3,y2+s-3,p);c.drawLine(x1+s/2,y1+s/2,x2+s/2,y2+s/2,p);}}}
